class RandomizedCollection {
    vector<int> vals;
    unordered_map<int, unordered_set<int>> mp;
public:
    RandomizedCollection() {

    }

    bool insert(int val) {
        bool isNew = (mp.find(val) == mp.end()) || mp[val].empty();
        vals.push_back(val);
        mp[val].insert((int)vals.size() - 1);
        return isNew;
    }

    bool remove(int val) {
        auto it = mp.find(val);
        if (it == mp.end() || it->second.empty()) return false;
        int idx = *it->second.begin();
        it->second.erase(it->second.begin());
        int last = vals.back();
        vals[idx] = last;
        mp[last].insert(idx);
        mp[last].erase((int)vals.size() - 1);
        vals.pop_back();
        if (mp[val].empty()) mp.erase(val);
        return true;
    }

    int getRandom() {
        return vals[rand() % (int)vals.size()];
    }
};

